insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-krupnik', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-krupnik/d71fb2f2-23ab-4055-a851-2042de77b343.webp', 20, 55, 4, null, null, '{}'::jsonb, '', array['post-polnische-suppen', 'post-sonntagsessen', 'post-polenladen']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-krupnik', 'de', 'Krupnik', 'krupnik', 'Eine wärmende polnische Suppe aus Perlgerste und Wurzelgemüse, wahlweise mit zartem Hühnerfleisch, ganz anders als die Erbsensuppe Grochówka oder die dunkle Pilzsuppe Zupa grzybowa.', '[{"text":"Die Perlgerste in einem Sieb gründlich abspülen. Zwiebel, Karotte, Sellerie und Petersilienwurzel würfeln und, falls verwendet, das Hühnerfleisch in Stücke schneiden. Die Zwiebel in Butter oder Öl glasig dünsten und die Gerste kurz mitrösten, bis sie leicht nussig duftet.","tip":"Krupnik lebt von der Gerste, nicht von Erbsen wie bei der [Grochówka](/de/rezepte/grochowka). Einen Überblick über die ganze Suppenfamilie gibt der Beitrag zu [polnischen Suppen](/de/blog/polnische-suppen)."},{"text":"Mit Wasser oder einer leichten Hühner- oder Gemüsebrühe auffüllen und Lorbeerblatt, Pfeffer sowie das restliche Wurzelgemüse hinzufügen. Die Suppe 35 bis 45 Minuten ruhig köcheln lassen, bis die Gerste weich ist und der Topf von selbst leicht bindet. Nicht pürieren, denn Krupnik soll nach Körnern schmecken und nicht nach Brei.","tip":"Wie du eine klare, kräftige Brühe hinbekommst, zeigt die [Rosół-Technik](/de/blog/rosol-technik). Gute Perlgerste findest du oft günstiger im [Polenladen](/de/blog/polenladen-einkaufen)."},{"text":"Die Hühnerstücke, falls verwendet, im Topf mitgaren oder bereits gegartes Fleisch erst gegen Ende zugeben, damit es nicht trocken wird. Mit Salz abschmecken und nur sparsam mit Säure arbeiten, denn Krupnik soll rund und getreidewarm schmecken, nicht sauer. Zum Schluss frischen Dill oder Petersilie einrühren.","tip":"Die Suppe bleibt hell und getreidig, ganz anders als der dunkle Trockenpilzsud der [Zupa grzybowa](/de/rezepte/zupa-grzybowa). Als Alltagsgericht passt sie gut in den Rahmen des [polnischen Sonntagsessens](/de/blog/sonntagsessen-polnisch)."},{"text":"Heiß in tiefen Tellern servieren, dazu passt frisches Brot. Reste halten sich gut im Kühlschrank und schmecken am zweiten Tag oft sogar runder, weil sich die Aromen setzen. Da die Gerste weiter Flüssigkeit zieht, beim Aufwärmen einfach etwas Brühe oder Wasser nachgießen.","tip":"Fehlt dir Perlgerste, findest du ehrliche Alternativen bei den [Ersatzprodukten](/de/blog/ersatzprodukte-de). Am Charakter ändert das nichts, es bleibt eine Gerstensuppe und keine Erbsensuppe."}]'::jsonb, 'Krupnik, getreidewarm, nach Gerste und Wurzelgemüse, Alltag und Sonntagstopf. Der Name Krupnik kommt vom altpolnischen Wort krupy, das schlicht Grütze oder Graupen bedeutet, und die Suppe reicht bis ins Mittelalter zurück. Ursprünglich war sie eine schlichte, oft fastentaugliche Grützsuppe für Bauern und Landarbeiter, erst ab dem 18. Jahrhundert fand sie den Weg auf bürgerliche und adlige Tische, unter anderem in Lucyna Ćwierczakiewiczowas berühmtes Kochbuch „365 obiadów za 5 złotych“ aus dem 19. Jahrhundert. Je nach Region unterscheidet sich Krupnik bis heute: In den Bergen der Podhale kommt traditionell mehr Wurzelgemüse hinein, in Masowien wird die Suppe deutlich fleischiger gekocht. Krupnik ist dabei weder die dicke Erbsensuppe [Grochówka](/de/rezepte/grochowka) noch die klare Festtagsbrühe [Rosół](/de/rezepte/rosol) noch die Sauerkrautsuppe [Kapuśniak](/de/rezepte/kapusniak). Einen Überblick über die ganze Suppenlandschaft gibt der Beitrag zu [polnischen Suppen](/de/blog/polnische-suppen).

## Einkaufen und kochen

Perlgerste ist der Charakterträger von Krupnik und liegt oft im [Polenladen](/de/blog/polenladen-einkaufen) griffbereit, genauso gut findest du sie aber auch im Getreideregal jedes Supermarkts. Dazu kommen Wurzelgemüse, Zwiebel, Lorbeer und Dill vom Markt, optional etwas Hühnerfleisch aus der Kühltheke. Fehlt eine bestimmte Gerstensorte, hilft der Beitrag zu [Ersatzprodukten](/de/blog/ersatzprodukte-de) weiter, ohne dass daraus eine Erbsensuppe wird. Getrocknete Erbsen oder ein Fond aus Trockenpilzen gehören nicht in den Topf, sonst landest du bei der [Grochówka](/de/rezepte/grochowka) oder der [Zupa grzybowa](/de/rezepte/zupa-grzybowa). Wie du eine klare Brühe als Basis kochst, zeigt die [Rosół-Technik](/de/blog/rosol-technik).

Die Gerste zunächst abspülen und kurz mitrösten, dann ruhig köcheln lassen, denn zu starkes Sprudeln macht den Topf trüb und gart die Körner ungleichmäßig. Fleisch und spätere Zutaten so timen, dass nichts zerkocht, während die Gerste selbst gerne etwas länger ziehen darf. Ein teilweises Pürieren ist möglich, aber selten nötig, denn Krupnik soll Biss haben und nicht zu Babybrei werden wie eine dicke [Grochówka](/de/rezepte/grochowka). Salz gestaffelt zugeben und mit Säure sparsam bleiben, denn diese Suppe lebt von der Wärme des Getreides und nicht von einem Waldpilzaroma wie die [Zupa grzybowa](/de/rezepte/zupa-grzybowa). Für die Klarheit der Brühe lohnt sich ein Blick in die [Rosół-Technik](/de/blog/rosol-technik).

Krupnik passt gut in den Alltag der Diaspora, weil ein Topf reicht: Gerste aus dem Vorrat, Gemüse aus dem Supermarkt, fertig. Du kannst gut für zwei Tage vorkochen, solltest beim Aufwärmen aber etwas Brühe nachgießen, weil die Gerste weiter Flüssigkeit zieht. Kinder dürfen die Gerste abmessen und Gemüse waschen, am heißen Topf übernehmen Erwachsene. Guten Vorrat an Gerste findest du im [Polenladen](/de/blog/polenladen-einkaufen), während die Kultur rund um den Sonntagstisch im [Sonntagsessen-Guide](/de/blog/sonntagsessen-polnisch) beschrieben ist.

## Am Tisch

Serviere Krupnik heiß mit reichlich Dill und frischem Brot dazu, als sättigender Starter oder als ganzes Mittagessen im Alltag, so wie es auch beim [polnischen Sonntagsessen](/de/blog/sonntagsessen-polnisch) üblich ist. Wer lieber Erbsen mag, findet sein Gericht bei der [Grochówka](/de/rezepte/grochowka), wer eine klare Festtagsbrühe sucht, bei [Rosół](/de/rezepte/rosol). Einen Überblick über die ganze Suppenfamilie liefert der Beitrag zu [polnischen Suppen](/de/blog/polnische-suppen), gute Zutaten dafür findest du im [Polenladen](/de/blog/polenladen-einkaufen).

Krupnik wird gelegentlich mit der Erbsensuppe [Grochówka](/de/rezepte/grochowka) oder der Pilzsuppe [Zupa grzybowa](/de/rezepte/zupa-grzybowa) verwechselt, dabei ist die Gerste der eigentliche Charakterträger. Zu starkes Pürieren macht aus der Suppe Brei, und ungewaschene Gerste trübt den Topf unnötig. Auch zu frühes Zugeben von bereits gegartem Fleisch lässt es beim Nachkochen austrocknen, deshalb kommt es besser erst gegen Ende in den Topf.

Mit mehr Hühnerfleisch wird Krupnik deutlich sättigender, in der vegetarischen Version bleibt das Fleisch ganz weg und wird im Titel ehrlich benannt. Getrocknete Pilze dürfen als leiser Unterton mitkochen, sollten die Suppe aber nicht zur [Zupa grzybowa](/de/rezepte/zupa-grzybowa) machen, denn der Fokus bleibt bei der Gerste. Passende Suppen-Nachbarn sind die [Grochówka](/de/rezepte/grochowka), der [Kapuśniak](/de/rezepte/kapusniak) und der [Rosół](/de/rezepte/rosol), einen Überblick über alle gibt der Beitrag zu [polnischen Suppen](/de/blog/polnische-suppen), und für den Sonntagstisch passt der [Sonntagsessen-Guide](/de/blog/sonntagsessen-polnisch).', 'Krupnik Rezept | Polnische Gerstensuppe | Alemniam', 'Krupnik: polnische Gerstensuppe mit Wurzelgemüse, anders als Grochówka und Zupa grzybowa. Bilingual mit Diaspora-Einkaufstipps für Deutschland.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-krupnik', 'pl', 'Krupnik', 'krupnik', 'Rozgrzewająca polska zupa z kaszy jęczmiennej i warzyw korzeniowych, opcjonalnie z delikatnym kurczakiem, zupełnie inna niż grochówka czy zupa grzybowa.', '[{"text":"Kaszę jęczmienną dokładnie przepłucz na sitku. Cebulę, marchew, seler i pietruszkę pokrój w kostkę, a jeśli używasz kurczaka, potnij go na kawałki. Cebulę zeszklij na maśle lub oleju, a potem krótko podsmaż kaszę, aż zacznie pachnieć orzechowo.","tip":"Krupnik zawdzięcza charakter kaszy, nie grochowi jak [grochówka](/pl/rezepte/grochowka). Przegląd całej rodziny zup znajdziesz w artykule o [polskich zupach](/pl/blog/polskie-zupy)."},{"text":"Zalej wodą lub lekkim bulionem drobiowym albo warzywnym, dodaj liść laurowy, pieprz i resztę warzyw korzeniowych. Gotuj spokojnie 35 do 45 minut, aż kasza zmięknie, a zupa sama lekko zgęstnieje. Nie blenduj jej, bo krupnik ma smakować ziarnami, a nie papką.","tip":"Jak ugotować klarowny, mocny bulion, pokazuje [technika rosołu](/pl/blog/jak-ugotowac-rosol). Dobrą kaszę jęczmienną często taniej kupisz w [sklepie polskim](/pl/blog/sklep-polski-zakupy)."},{"text":"Kurczaka, jeśli go używasz, dogotuj razem z zupą, a już ugotowane mięso dodaj dopiero pod koniec, żeby się nie wysuszyło. Dopraw solą i sięgaj po kwas oszczędnie, bo krupnik ma być łagodny i zbożowy, a nie kwaśny. Na koniec wmieszaj świeży koperek lub natkę pietruszki.","tip":"Zupa zostaje jasna i zbożowa, zupełnie inna niż ciemny wywar z suszonych grzybów w [zupie grzybowej](/pl/rezepte/zupa-grzybowa). Jako danie na co dzień pasuje dobrze w duchu [obiadu niedzielnego](/pl/blog/obiad-niedzielny)."},{"text":"Podawaj gorącą w głębokich talerzach, z chlebem obok. Resztki dobrze się przechowują i nazajutrz często smakują jeszcze lepiej, bo smaki się przegryzają. Kasza dalej wchłania płyn, więc przy odgrzewaniu po prostu dolej trochę bulionu lub wody.","tip":"Jeśli brakuje ci kaszy jęczmiennej, uczciwe zamienniki znajdziesz w artykule o [zamiennikach składników](/pl/blog/zamienniki-skladnikow). Charakter zupy się nie zmienia, to nadal zupa jęczmienna, a nie grochowa."}]'::jsonb, 'Krupnik, zbożowy, od kaszy jęczmiennej i włoszczyzny, codzienność i niedziela. Nazwa krupnik pochodzi od staropolskiego słowa krupy, czyli kasza, a sama zupa sięga korzeniami średniowiecza. Początkowo była to prosta, często postna polewka z kaszą, jedzona przez chłopów i robotników rolnych, dopiero od XVIII wieku trafiła też na stoły mieszczańskie i szlacheckie, między innymi do słynnej książki kucharskiej Lucyny Ćwierczakiewiczowej „365 obiadów za 5 złotych” z XIX wieku. Do dziś krupnik różni się w zależności od regionu: na Podhalu dodaje się więcej warzyw korzeniowych, na Mazowszu zupa bywa bardziej mięsna. To ani gęsta [grochówka](/pl/rezepte/grochowka), ani klarowny [rosół](/pl/rezepte/rosol), ani kiszony [kapuśniak](/pl/rezepte/kapusniak). Przegląd całej rodziny zup znajdziesz w artykule o [polskich zupach](/pl/blog/polskie-zupy).

## Zakupy i gotowanie

Kasza jęczmienna niesie cały charakter krupniku i często czeka gotowa w [sklepie polskim](/pl/blog/sklep-polski-zakupy), ale równie dobrze znajdziesz ją w dziale zbożowym każdego marketu. Do tego warzywa korzeniowe, cebula, liść laurowy i koperek z targu, opcjonalnie trochę kurczaka z lady chłodniczej. Gdy brakuje konkretnej kaszy, pomogą uczciwe [zamienniki składników](/pl/blog/zamienniki-skladnikow), bez zamiany zupy w grochową. Suszony groch albo wywar z suszonych grzybów nie pasują do tego garnka, bo wtedy wychodzi [grochówka](/pl/rezepte/grochowka) albo [zupa grzybowa](/pl/rezepte/zupa-grzybowa). Jak ugotować klarowny bulion jako bazę, pokazuje [technika rosołu](/pl/blog/jak-ugotowac-rosol).

Kaszę najpierw przepłucz i krótko podsmaż, a potem gotuj spokojnie, bo mocne bulgotanie mąci zupę i nierówno gotuje ziarna. Mięso i późniejsze dodatki dodawaj w takim momencie, żeby nic się nie rozgotowało, a sama kasza spokojnie może pociągnąć dłużej. Częściowe zblendowanie jest możliwe, ale rzadko potrzebne, bo krupnik ma mieć wyczuwalne ziarna, a nie zamieniać się w papkę jak gęsta [grochówka](/pl/rezepte/grochowka). Sól dodawaj etapami, a z kwasem obchodź się oszczędnie, bo ta zupa żyje ciepłem zboża, a nie aromatem leśnych grzybów jak [zupa grzybowa](/pl/rezepte/zupa-grzybowa). Klarowność bulionu opisuje bliżej [technika rosołu](/pl/blog/jak-ugotowac-rosol).

Krupnik dobrze wpisuje się w codzienność diaspory, bo wystarczy jeden garnek: kasza ze spiżarni, warzywa z marketu i gotowe. Można spokojnie ugotować zapas na dwa dni, tylko przy odgrzewaniu warto dolać trochę bulionu, bo kasza dalej wchłania płyn. Dzieci mogą odmierzyć kaszę i umyć warzywa, przy gorącym garnku pomagają dorośli. Dobry zapas kaszy znajdziesz w [sklepie polskim](/pl/blog/sklep-polski-zakupy), a o kulturze niedzielnego stołu opowiada [obiad niedzielny](/pl/blog/obiad-niedzielny).

## Przy stole

Podawaj krupnik gorący, z dużą ilością koperku i świeżym chlebem obok, jako sycącą przystawkę albo cały obiad na co dzień, podobnie jak przy [obiedzie niedzielnym](/pl/blog/obiad-niedzielny). Kto woli groch, znajdzie swoje danie w [grochówce](/pl/rezepte/grochowka), a kto szuka klarownego wywaru świątecznego, w [rosole](/pl/rezepte/rosol). Przegląd całej rodziny zup daje artykuł o [polskich zupach](/pl/blog/polskie-zupy), a dobre składniki znajdziesz w [sklepie polskim](/pl/blog/sklep-polski-zakupy).

Krupnik bywa mylony z grochową [grochówką](/pl/rezepte/grochowka) albo z [zupą grzybową](/pl/rezepte/zupa-grzybowa), a przecież to kasza jęczmienna nadaje mu charakter. Zbyt mocne blendowanie zamienia zupę w papkę, a nieprzepłukana kasza niepotrzebnie mąci wywar. Zbyt wczesne dodanie już ugotowanego mięsa sprawia, że podczas dalszego gotowania wysycha, dlatego lepiej wrzucić je dopiero pod koniec.

Z większą ilością kurczaka krupnik robi się dużo bardziej sycący, a w wersji wegetariańskiej mięso po prostu znika i jest to uczciwie napisane w tytule. Suszone grzyby mogą dorzucić cichy podton, ale nie powinny zamieniać zupy w [zupę grzybową](/pl/rezepte/zupa-grzybowa), bo fokus zostaje przy kaszy. Pasującymi sąsiadami są [grochówka](/pl/rezepte/grochowka), [kapuśniak](/pl/rezepte/kapusniak) i [rosół](/pl/rezepte/rosol), ich przegląd znajdziesz w artykule o [polskich zupach](/pl/blog/polskie-zupy), a do niedzielnego stołu pasuje [obiad niedzielny](/pl/blog/obiad-niedzielny).', 'Krupnik przepis | Zupa jęczmienna | Alemniam', 'Krupnik: zupa z kaszy jęczmiennej i warzyw, inna niż grochówka i zupa grzybowa. Dwujęzycznie, z poradami zakupowymi w Niemczech.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
